#include <iostream>
#include <string>
#include <vector>
#include <functional>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string a, b;
    cin >> a >> b;

    const int n = static_cast<int>(a.size());
    const int m = static_cast<int>(b.size());

    auto construct = [&](int len) -> string {
        if (len < m) return "";

        const bool sameLength = (len == n);
        vector<vector<vector<int>>> memo(
            len + 1, vector<vector<int>>(m + 1, vector<int>(2, -1))
        );

        function<bool(int, int, int)> possible = [&](int pos, int used, int greater) {
            if (pos == len)
                return used == m && (!sameLength || greater);

            int &res = memo[pos][used][greater];
            if (res != -1) return res;

            int firstDigit = (pos == 0 ? 1 : 0);

            for (int d = firstDigit; d <= 9; ++d) {
                int nextGreater = greater;

                if (sameLength && !greater) {
                    int limit = a[pos] - '0';
                    if (d < limit) continue;
                    if (d > limit) nextGreater = 1;
                }

                int nextUsed = used;
                if (d == 4 || d == 7) {
                    if (used >= m || b[used] - '0' != d) continue;
                    ++nextUsed;
                }

                if (possible(pos + 1, nextUsed, nextGreater))
                    return res = 1;
            }

            return res = 0;
        };

        if (!possible(0, 0, sameLength ? 0 : 1))
            return "";

        string answer;
        int used = 0;
        int greater = sameLength ? 0 : 1;

        for (int pos = 0; pos < len; ++pos) {
            int firstDigit = (pos == 0 ? 1 : 0);

            for (int d = firstDigit; d <= 9; ++d) {
                int nextGreater = greater;

                if (sameLength && !greater) {
                    int limit = a[pos] - '0';
                    if (d < limit) continue;
                    if (d > limit) nextGreater = 1;
                }

                int nextUsed = used;
                if (d == 4 || d == 7) {
                    if (used >= m || b[used] - '0' != d) continue;
                    ++nextUsed;
                }

                if (possible(pos + 1, nextUsed, nextGreater)) {
                    answer.push_back(char('0' + d));
                    used = nextUsed;
                    greater = nextGreater;
                    break;
                }
            }
        }

        return answer;
    };

    string answer = construct(n);
    if (answer.empty())
        answer = construct(max(n + 1, m));

    cout << answer << '\n';
    return 0;
}

