#include <iostream>
using namespace std;

bool check(long long a, long long b)
{
    long long lucky = 0;
    long long place = 1;

    while (a > 0)
    {
        int digit = a % 10;
        if (digit == 4 || digit == 7)
        {
            lucky += digit * place;
            place *= 10;
        }
        a /= 10;
    }

    return lucky == b;
}

int main()
{
    long long a, b;
    cin >> a >> b;

    if (b > a)
    {
        cout << b << '\n';
    }
    else if (b == a)
    {
        cout << 1 << b << '\n';
    }
    else
    {
        for (long long i = a + 1;; ++i)
        {
            if (check(i, b))
            {
                cout << i << '\n';
                break;
            }
        }
    }

    return 0;
}

